#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define MAX_N 60
static long long memo[MAX_N + 1][MAX_N + 1];
static unsigned char computed[MAX_N + 1][MAX_N + 1];

static long long binom(int n, int k)
{
    if (k == 0 || k == n) return 1;
    if (n < 0 || k < 0) return 0;
    if (n < k) return 0;
    if (computed[n][k]) return memo[n][k];
    long long v = binom(n - 1, k - 1) + binom(n - 1, k);
    memo[n][k] = v;
    computed[n][k] = 1;
    return v;
}

int main(int argc, char *argv[])
{
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }
    char *end1, *end2;
    long n_long = strtol(argv[1], &end1, 10);
    long k_long = strtol(argv[2], &end2, 10);
    if (end1 == argv[1] || *end1 != '\0' || end2 == argv[2] || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (n_long < 0 || n_long > MAX_N) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    long long result = binom((int)n_long, (int)k_long);
    printf("%lld\n", result);
    return 0;
}
